select pg_temp.check_true(public.get_admin_business_privacy_correction_v1(current_setting('test.privacy.empty')::uuid)->>'blocked_reason'='no_application','missing draft cannot be inferred or fabricated');
select set_config('test.privacy.erase',public.admin_business_privacy_open_v1(current_setting('test.privacy.owner')::uuid,'erasure','case:verified-erasure',now(),gen_random_uuid())->>'id',true);
