select pg_temp.expect_error($q$select public.admin_business_privacy_command_v1(current_setting('test.privacy.access')::uuid,1,'release_hold','legal:wrong-case',gen_random_uuid())$q$,'original case');
select pg_temp.expect_error($q$select public.admin_business_privacy_command_v1(current_setting('test.privacy.access')::uuid,1,'hold','legal:replace-hold',gen_random_uuid())$q$,'Existing hold');
select pg_temp.expect_error($q$select public.admin_business_privacy_command_v1(current_setting('test.privacy.erase')::uuid,2,'prepare_erasure','case:erase-authorized',gen_random_uuid())$q$,'Legal hold');
select public.admin_business_privacy_command_v1(current_setting('test.privacy.erase')::uuid,2,'release_hold','legal:release-0001',gen_random_uuid());
select pg_temp.expect_error($q$select public.admin_business_privacy_command_v1(current_setting('test.privacy.erase')::uuid,2,'prepare_erasure','case:erase-authorized',gen_random_uuid())$q$,'case changed');
select public.admin_business_privacy_command_v1(current_setting('test.privacy.erase')::uuid,3,'prepare_erasure','case:erase-authorized','79000000-0000-4000-8000-000000000011');
select pg_temp.check_true(public.get_admin_business_privacy_correction_v1(current_setting('test.privacy.correction')::uuid)->>'blocked_reason'='erasure_prepared','prepared erasure blocks current draft correction');
select pg_temp.check_true(public.admin_business_privacy_command_v1(current_setting('test.privacy.erase')::uuid,3,'prepare_erasure','case:erase-authorized','79000000-0000-4000-8000-000000000011')->>'revision'='4','erasure preparation replays without duplicate audit');
select pg_temp.expect_error($q$select public.admin_business_privacy_command_v1(current_setting('test.privacy.erase')::uuid,4,'complete','case:provider-reviewed',gen_random_uuid())$q$,'Primary erasure');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.privacy.owner'),'role','doji_business','aal','aal2')::text,true);
set local role doji_business;
select pg_temp.expect_error('select public.get_business_application_v1()','Business access disabled');
reset role;
set local role service_role;
select pg_temp.check_true(public.claim_business_erasure_v1(current_setting('test.privacy.erase')::uuid,'79000000-0000-4000-8000-000000000012')->>'delete_authorized'='true','exact approved erasure grants one Auth deletion');
select pg_temp.check_true(public.claim_business_erasure_v1(current_setting('test.privacy.erase')::uuid,'79000000-0000-4000-8000-000000000012')->>'delete_authorized'='false','execution retry reconciles but cannot blindly repeat Auth deletion');
select pg_temp.expect_error($q$select public.claim_business_erasure_v1(current_setting('test.privacy.erase')::uuid,gen_random_uuid())$q$,'Different erasure execution');
select pg_temp.expect_error($q$select public.finish_business_erasure_v1(current_setting('test.privacy.erase')::uuid,'79000000-0000-4000-8000-000000000012')$q$,'Auth deletion not confirmed');
reset role;
-- Synthetic database-only simulation; real Auth API path has separate integration test.
delete from auth.users where id=current_setting('test.privacy.owner')::uuid;
set local role service_role;
select pg_temp.check_true(public.finish_business_erasure_v1(current_setting('test.privacy.erase')::uuid,'79000000-0000-4000-8000-000000000012')->>'state'='primary_erased','primary erasure completes only after exact Auth absence');
select pg_temp.check_true(public.finish_business_erasure_v1(current_setting('test.privacy.erase')::uuid,'79000000-0000-4000-8000-000000000012')->>'state'='primary_erased','primary completion retry is idempotent');
reset role;
select pg_temp.check_true((select details='{}' and response='' from business_private.applications where id=current_setting('test.privacy.app')::uuid),'erasure removes current application content');
select pg_temp.check_true(not exists(select 1 from business_private.submissions where application_id=current_setting('test.privacy.app')::uuid and details<>'{}'),'erasure removes historical submission content');
select pg_temp.check_true(not exists(select 1 from business_private.history where application_id=current_setting('test.privacy.app')::uuid and (response<>'' or internal_note<>'')),'erasure removes business review notes');
select pg_temp.check_true((select cleanup_email is null from business_private.privacy_cases where id=current_setting('test.privacy.erase')::uuid),'erasure clears temporary email cleanup key');
select pg_temp.check_true(exists(select 1 from auth.users where id=current_setting('test.member')::uuid),'member identity survives business erasure');
select pg_temp.check_true(exists(select 1 from business_private.signup_agreements where account_id=current_setting('test.privacy.owner')::uuid),'minimal version evidence retained separately from erased content');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.employee'),'role','doji_employee','aal','aal2')::text,true);
set local role doji_employee;
select pg_temp.check_true(public.admin_business_privacy_command_v1(current_setting('test.privacy.erase')::uuid,6,'complete','case:provider-backup-review',gen_random_uuid())->>'state'='completed','request completion requires separate provider and backup review reference');
reset role;
